(()=>{
const rates={QAR:1,USD:0.274725,EUR:0.2345,GBP:0.2045,AED:1.0088,SAR:1.0302,KWD:0.0839,BHD:0.1033,OMR:0.1057,TND:0.812908,MAD:2.63508};
const symbols={QAR:'QAR',USD:'$',EUR:'€',GBP:'£',AED:'AED',SAR:'SAR',KWD:'KWD',BHD:'BHD',OMR:'OMR',TND:'TND',MAD:'MAD'};
let currency=localStorage.getItem('sultana-currency')||'QAR';if(!rates[currency])currency='QAR';
const fmt=n=>{const v=n*rates[currency];return `${symbols[currency]} ${v.toLocaleString(undefined,{minimumFractionDigits:currency==='QAR'?0:2,maximumFractionDigits:2})}`};
const priceSelectors='.price,.detail-price,#bag-total,.cart-total,.cart-subtotal,.subtotal,.total,[data-price-display],[data-money]';
const captureQar=el=>{if(el.dataset.qar)return;const m=el.textContent.match(/QAR\s*([\d,.]+)/i);if(m)el.dataset.qar=m[1].replace(/,/g,'')};
const convertText=()=>document.querySelectorAll(priceSelectors).forEach(el=>{captureQar(el);if(el.dataset.qar)el.textContent=fmt(Number(el.dataset.qar))});
const ensureOptions=()=>document.querySelectorAll('#currency-select').forEach(s=>{if(!s.querySelector('option[value="TND"]'))s.insertAdjacentHTML('beforeend','<option value="TND">🇹🇳 TND</option>');if(!s.querySelector('option[value="MAD"]'))s.insertAdjacentHTML('beforeend','<option value="MAD">🇲🇦 MAD</option>');s.value=currency});
const hideOldVisualMenu=()=>document.querySelectorAll('section').forEach(sec=>{const t=(sec.textContent||'').replace(/\s+/g,' ').toLowerCase();if((t.includes('explore sultana')||t.includes('discover our world'))&&t.includes('wedding')&&t.includes('hospitality'))sec.style.display='none'});
const installHeader=()=>{const h=document.querySelector('header');if(!h)return;const brand=h.querySelector('.brand'),actions=h.querySelector('.header-actions');if(!brand||!actions)return;
let nav=h.querySelector('.desktop-luxury-nav');if(!nav){nav=document.createElement('nav');nav.className='desktop-luxury-nav';h.appendChild(nav)}nav.innerHTML='<a href="/">Home</a><a href="/shop/?collection=perfume#collection">Perfumes</a><a href="/room-sprays/">Luxury Spray</a><a href="/oud-bakhoor/">Oud &amp; Bakhoor</a><a href="/b2b/">B2B</a><a href="/our-story/">Our Story</a><a href="/contact/">Contact</a>';
let left=h.querySelector('.desktop-header-left');if(!left){left=document.createElement('div');left.className='desktop-header-left';left.innerHTML='<span>Qatar</span><span class="sep">|</span><span class="desktop-currency-slot"></span><span class="sep">|</span><span class="desktop-language-slot"></span>';h.appendChild(left)}
const cur=actions.querySelector('#currency-select'),lang=actions.querySelector('.language-switch'),cslot=left.querySelector('.desktop-currency-slot'),lslot=left.querySelector('.desktop-language-slot');if(cur&&cslot&&!cslot.firstChild){const clone=cur.cloneNode(true);clone.id='desktop-currency-select';clone.value=currency;cslot.appendChild(clone)}if(lang&&lslot&&!lslot.firstChild){const clone=lang.cloneNode(true);clone.classList.add('desktop-language-switch');lslot.appendChild(clone)}
let style=document.getElementById('stable-global-header');if(!style){style=document.createElement('style');style.id='stable-global-header';document.head.appendChild(style)}style.textContent=`@media(min-width:851px){header{height:160px!important;min-height:160px!important;padding:0 5%!important;display:grid!important;grid-template-columns:1fr auto 1fr!important;grid-template-rows:112px 48px!important;align-items:center!important;background:#fffdfa!important;position:relative!important;overflow:visible!important}header>.brand{grid-column:2!important;grid-row:1!important;justify-self:center!important;position:static!important;transform:none!important;width:92px!important;height:102px!important;margin:0!important}header>.brand img{width:100%!important;height:100%!important;object-fit:contain!important}header>.header-actions{grid-column:3!important;grid-row:1!important;justify-self:end!important;display:flex!important;visibility:visible!important;opacity:1!important;align-items:center!important;gap:16px!important;position:static!important;transform:none!important}header>.header-actions #search-open,header>.header-actions #bag-open{display:inline-flex!important;visibility:visible!important;opacity:1!important}header>.header-actions .currency-select,header>.header-actions .language-switch{display:none!important}header>#main-navigation,header>.menu-toggle{display:none!important}.desktop-header-left{grid-column:1!important;grid-row:1!important;justify-self:start!important;display:flex!important;align-items:center!important;gap:11px!important;font-size:12px!important;white-space:nowrap!important}.desktop-header-left select,.desktop-header-left a{border:0!important;background:transparent!important;padding:4px 0!important;font-size:12px!important}.desktop-header-left .sep{color:#9b9286}.desktop-luxury-nav{display:flex!important;visibility:visible!important;opacity:1!important;position:absolute!important;left:0!important;right:0!important;bottom:0!important;top:auto!important;transform:none!important;z-index:50!important;width:100%!important;height:48px!important;min-height:48px!important;align-items:center!important;justify-content:center!important;gap:clamp(24px,3vw,50px)!important;background:#fffdfa!important;border:0!important;margin:0!important;padding:0 24px!important;overflow:visible!important}.desktop-luxury-nav a{display:block!important;visibility:visible!important;opacity:1!important;color:#17130f!important;text-decoration:none!important;font:500 11px/48px Arial,sans-serif!important;letter-spacing:.35px!important;text-transform:uppercase!important;white-space:nowrap!important;margin:0!important;padding:0!important}}@media(max-width:850px){.desktop-luxury-nav,.desktop-header-left{display:none!important}}`};
const sync=()=>{ensureOptions();convertText();installHeader();hideOldVisualMenu()};document.addEventListener('change',e=>{if(e.target.id==='currency-select'||e.target.id==='desktop-currency-select'){currency=e.target.value;localStorage.setItem('sultana-currency',currency);document.querySelectorAll('#currency-select,#desktop-currency-select').forEach(s=>s.value=currency);convertText()}});document.addEventListener('DOMContentLoaded',sync);window.addEventListener('load',sync);window.SultanaCurrency={formatQAR:fmt,get:()=>currency,refresh:sync};
})();